import type { StoryEnrichmentInput, StoryEnrichmentIntent, StoryEnrichmentProvider, StoryEnrichmentResult } from "./types";
import { validateStoryEnrichmentInput } from "./types";

interface OpenAIResponse { model?: string; output?: Array<{ type?: string; content?: Array<{ type?: string; text?: string }> }>; error?: { message?: string } | null; }

function outputText(response: OpenAIResponse) {
  return (response.output ?? []).flatMap((item) => item.content ?? []).filter((item) => item.type === "output_text" && typeof item.text === "string").map((item) => item.text).join("\n").trim();
}

function intentInstruction(intent: StoryEnrichmentIntent | undefined) {
  switch (intent) {
    case "sweeter": return "Write one warm, sincere share caption. Keep it concise and grounded only in supplied facts; do not invent intimacy or quote hidden messages.";
    case "funnier": return "Write one playful, funny chapter caption grounded only in supplied facts. Avoid insults, relationship judgments, or invented events.";
    case "birthday-caption": return "Write one celebratory birthday share caption using only supplied facts and safe chapters. Keep identities unknown unless explicitly supplied in a consented snippet.";
    case "anniversary-caption": return "Write one warm anniversary share caption using only supplied facts and safe chapters. Do not infer relationship health or private events.";
    case "shorter-share-caption": return "Write one very short social share caption, ideally under 140 characters, using only supplied facts and safe chapters.";
    default: return "Return concise editable copy: a recap paragraph, 3 alternate chapter titles, and a short narration script.";
  }
}

export class OpenAIStoryEnrichmentProvider implements StoryEnrichmentProvider {
  readonly name = "openai";
  constructor(private readonly apiKey: string, private readonly model = "gpt-5.6-luna") {}

  async enrich(input: StoryEnrichmentInput): Promise<StoryEnrichmentResult> {
    validateStoryEnrichmentInput(input);
    const payload = { product: input.product, mode: input.mode, intent: input.intent ?? "recap", facts: input.facts, chapters: input.chapters, ...(input.selectedSnippet?.trim() ? { userSelectedSnippet: input.selectedSnippet.trim() } : {}) };
    const response = await fetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: { Authorization: `Bearer ${this.apiKey}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model: this.model,
        store: false,
        max_output_tokens: 700,
        instructions: `You enrich a personal story using only supplied derived facts, safe chapters, and any explicitly user-selected snippet. Do not infer private facts, relationship health, diagnoses, identities, or hidden message content. ${intentInstruction(input.intent)}`,
        input: JSON.stringify(payload),
        text: { verbosity: "low" },
      }),
      cache: "no-store",
    });
    const data = await response.json().catch(() => ({})) as OpenAIResponse;
    if (!response.ok) throw new Error(data.error?.message ?? "AI enrichment provider failed.");
    const text = outputText(data);
    if (!text) throw new Error("AI enrichment returned no text.");
    return { text, provider: this.name, model: data.model ?? this.model };
  }
}

export function getStoryEnrichmentProvider(): StoryEnrichmentProvider | null {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) return null;
  return new OpenAIStoryEnrichmentProvider(apiKey, process.env.OPENAI_STORY_MODEL || "gpt-5.6-luna");
}

import type { StoryChapter } from "@/platform/types";

export const STORY_ENRICHMENT_INTENTS = ["recap", "sweeter", "funnier", "birthday-caption", "anniversary-caption", "shorter-share-caption"] as const;
export type StoryEnrichmentIntent = (typeof STORY_ENRICHMENT_INTENTS)[number];

export interface StoryEnrichmentInput {
  product: "threadtales" | "myyear" | "petlife";
  mode?: string;
  intent?: StoryEnrichmentIntent;
  facts: Record<string, string | number | boolean | null>;
  chapters: Array<Pick<StoryChapter, "id" | "type" | "title" | "subtitle" | "metric" | "supportingText" | "renderVariant">>;
  selectedSnippet?: string;
  snippetConsent?: boolean;
}

export interface StoryEnrichmentResult { text: string; provider: string; model: string; }
export interface StoryEnrichmentProvider { readonly name: string; enrich(input: StoryEnrichmentInput): Promise<StoryEnrichmentResult>; }

const THREADTALES_FACTS = new Set(["totalMessages","totalWords","daysTogether","activeDays","longestStreak","longestSilenceDays","medianReplyMinutes","peakHour","favoriteWeekday","lateNightMessages","questionsAsked","laughSignals","heartSignals","mediaSignals","conversationBalance","yearCount"]);
const FORBIDDEN_KEYS = /raw|messageText|chatMessages|participants|topWords|sender|transcript/i;

export function validateStoryEnrichmentInput(input: StoryEnrichmentInput) {
  if (!input || !["threadtales","myyear","petlife"].includes(input.product)) throw new Error("Unsupported AI enrichment product.");
  if (input.intent !== undefined && !STORY_ENRICHMENT_INTENTS.includes(input.intent)) throw new Error("Unsupported AI enrichment intent.");
  const entries = Object.entries(input.facts ?? {});
  if (entries.length > 30) throw new Error("Too many enrichment facts.");
  for (const [key, value] of entries) {
    if (FORBIDDEN_KEYS.test(key)) throw new Error(`AI enrichment rejected private-content field: ${key}`);
    if (input.product === "threadtales" && !THREADTALES_FACTS.has(key)) throw new Error(`ThreadTales AI fact is not allowlisted: ${key}`);
    if (!["string","number","boolean"].includes(typeof value) && value !== null) throw new Error("AI facts must contain derived scalar values only.");
    if (typeof value === "string" && value.length > 160) throw new Error("AI fact text is too long.");
  }
  if (!Array.isArray(input.chapters) || input.chapters.length > 20) throw new Error("Invalid enrichment chapter list.");
  for (const chapter of input.chapters) {
    const joined = [chapter.id, chapter.type, chapter.title, chapter.subtitle, chapter.metric, chapter.supportingText, chapter.renderVariant].filter((value) => value !== undefined).join(" ");
    if (joined.length > 1000) throw new Error("AI chapter input is too long.");
  }
  const snippet = input.selectedSnippet?.trim();
  if (snippet) {
    if (!input.snippetConsent) throw new Error("Explicit consent is required before sending a selected snippet to AI.");
    if (snippet.length > 600) throw new Error("Selected AI snippet must be 600 characters or fewer.");
  }
}

export const PREMIUM_ENTITLEMENT_STORAGE_KEY = "threadtales:premium-entitlement";

export async function validateBrowserPremiumEntitlement() {
  if (typeof window === "undefined") return false;
  const token = window.localStorage.getItem(PREMIUM_ENTITLEMENT_STORAGE_KEY);
  if (!token) return false;
  try {
    const response = await fetch("/api/entitlements", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token }) });
    if (!response.ok) return false;
    const data = await response.json() as { valid?: boolean };
    return Boolean(data.valid);
  } catch {
    return false;
  }
}

