const statusSet = new Set([
  "trialing",
  "active",
  "past_due",
  "unpaid",
  "canceled",
  "incomplete",
  "incomplete_expired",
  "paused",
]);

function unixDate(value: unknown) {
  return typeof value === "number" && Number.isFinite(value)
    ? new Date(value * 1000).toISOString()
    : null;
}

function stringId(value: unknown) {
  if (typeof value === "string") return value;
  if (
    value
    && typeof value === "object"
    && "id" in value
    && typeof (value as { id?: unknown }).id === "string"
  ) {
    return (value as { id: string }).id;
  }
  return "";
}

function invoiceSubscriptionId(object: Record<string, unknown>) {
  const parent =
    object.parent && typeof object.parent === "object"
      ? (object.parent as Record<string, unknown>)
      : null;
  const subscriptionDetails =
    parent?.subscription_details
    && typeof parent.subscription_details === "object"
      ? (parent.subscription_details as Record<string, unknown>)
      : null;

  // Stripe Basil+ moved invoice.subscription to
  // invoice.parent.subscription_details.subscription. Keep the old field as
  // a compatibility fallback for events created with an older API version.
  return stringId(subscriptionDetails?.subscription) || stringId(object.subscription);
}

async function getSubscriptionByStripeId(subscriptionId: string) {
  const rows = await supabaseAdminRest<SubscriptionRecord[]>(
    `subscriptions?stripe_subscription_id=eq.${encodeURIComponent(subscriptionId)}&select=user_id,plan_slug,billing_interval&limit=1`,
  );
  return rows[0] ?? null;
}

export async function hasProcessedStripeEvent(id: string) {
  const rows = await supabaseAdminRest<Array<{ event_id: string }>>(
    `stripe_events?event_id=eq.${encodeURIComponent(id)}&select=event_id&limit=1`,
  );
  return Boolean(rows[0]);
}

export async function recordStripeEvent(id: string, type: string) {
  await supabaseAdminRest("stripe_events?on_conflict=event_id", {
    method: "POST",
    headers: { Prefer: "resolution=ignore-duplicates,return=minimal" },
    body: JSON.stringify({ event_id: id, event_type: type }),
  });
}

export async function reconcileSubscriptionEvent(event: StripeEvent) {
  const object = event.data?.object ?? {};

  if (
    event.type === "checkout.session.completed"
    && object.mode === "subscription"
  ) {
    const metadata =
      object.metadata && typeof object.metadata === "object"
        ? (object.metadata as Record<string, unknown>)
        : {};
    const userId =
      typeof metadata.user_id === "string" ? metadata.user_id : "";
    const plan = metadata.plan;
    const interval = metadata.interval;
    const subscriptionId = stringId(object.subscription);
    const customerId = stringId(object.customer);

    if (
      !userId
      || !subscriptionId
      || !customerId
      || !isPlanSlug(plan)
      || plan === "free"
      || (interval !== "month" && interval !== "year")
    ) {
      return false;
    }

    const paymentStatus = object.payment_status;
    await supabaseAdminRest(
      "subscriptions?on_conflict=stripe_subscription_id",
      {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify({
          user_id: userId,
          stripe_subscription_id: subscriptionId,
          stripe_customer_id: customerId,
          plan_slug: plan,
          billing_interval: interval,
          status:
            paymentStatus === "paid" || paymentStatus === "no_payment_required"
              ? "active"
              : "incomplete",
          updated_at: new Date().toISOString(),
        }),
      },
    );
    return true;
  }

  if (event.type?.startsWith("customer.subscription.")) {
    const subscriptionId = stringId(object.id);
    if (!subscriptionId) return false;

    const existing = await getSubscriptionByStripeId(subscriptionId);
    const metadata =
      object.metadata && typeof object.metadata === "object"
        ? (object.metadata as Record<string, unknown>)
        : {};
    const userId =
      typeof metadata.user_id === "string"
        ? metadata.user_id
        : existing?.user_id;
    const planCandidate =
      typeof metadata.plan === "string"
        ? metadata.plan
        : existing?.plan_slug;
    const intervalCandidate =
      metadata.interval === "month" || metadata.interval === "year"
        ? metadata.interval
        : existing?.billing_interval;

    if (
      !userId
      || !isPlanSlug(planCandidate)
      || planCandidate === "free"
    ) {
      return false;
    }

    const rawStatus =
      typeof object.status === "string" && statusSet.has(object.status)
        ? object.status
        : event.type === "customer.subscription.deleted"
          ? "canceled"
          : "incomplete";
    const customerId = stringId(object.customer) || null;

    await supabaseAdminRest(
      "subscriptions?on_conflict=stripe_subscription_id",
      {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify({
          user_id: userId,
          stripe_subscription_id: subscriptionId,
          stripe_customer_id: customerId,
          plan_slug: planCandidate,
          billing_interval: intervalCandidate ?? null,
          status: rawStatus,
          current_period_end: unixDate(object.current_period_end),
          cancel_at_period_end: Boolean(object.cancel_at_period_end),
          updated_at: new Date().toISOString(),
        }),
      },
    );
    return true;
  }

  if (
    event.type === "invoice.paid"
    || event.type === "invoice.payment_failed"
  ) {
    const subscriptionId = invoiceSubscriptionId(object);
    if (!subscriptionId) return false;

    const existing = await getSubscriptionByStripeId(subscriptionId);
    if (!existing) return false;

    await supabaseAdminRest(
      `subscriptions?stripe_subscription_id=eq.${encodeURIComponent(subscriptionId)}`,
      {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify({
          status: event.type === "invoice.paid" ? "active" : "past_due",
          updated_at: new Date().toISOString(),
        }),
      },
    );
    return true;
  }

  return false;
}

import { supabaseRest } from "@/platform/persistence/supabase-rest";
import type { PlanSlug } from "./plans";
import { isPlanSlug } from "./plans";

export interface SubscriptionRecord {
  plan_slug: PlanSlug;
  status: string;
  billing_interval?: "month" | "year" | null;
  current_period_end?: string | null;
  cancel_at_period_end?: boolean;
}

export async function getUserSubscription(userId: string, accessToken: string): Promise<SubscriptionRecord> {
  const rows = await supabaseRest<SubscriptionRecord[]>(`subscriptions?user_id=eq.${encodeURIComponent(userId)}&select=plan_slug,status,billing_interval,current_period_end,cancel_at_period_end&order=updated_at.desc&limit=1`, accessToken);
  const row = rows[0];
  if (!row || !isPlanSlug(row.plan_slug) || !["active", "trialing"].includes(row.status)) return { plan_slug: "free", status: "free", billing_interval: null, current_period_end: null, cancel_at_period_end: false };
  return row;
}

import { supabaseAdminRest } from "@/platform/persistence/supabase-rest";
import { isSupabaseServerConfigured } from "@/platform/persistence/config";

const PREMIUM_PRODUCT = "threadtales-premium";

type StripeCheckoutCompletedEvent = {
  type?: unknown;
  data?: {
    object?: {
      id?: unknown;
      payment_status?: unknown;
      metadata?: unknown;
    };
  };
};

function isCompletedPremiumCheckout(event: StripeCheckoutCompletedEvent) {
  const checkout = event.data?.object;
  return event.type === "checkout.session.completed"
    && typeof checkout?.id === "string"
    && /^cs_(?:test_|live_)?[A-Za-z0-9_]+$/.test(checkout.id)
    && checkout.payment_status === "paid"
    && typeof checkout.metadata === "object"
    && checkout.metadata !== null
    && (checkout.metadata as Record<string, unknown>).entitlement === PREMIUM_PRODUCT;
}

/**
 * Records a verified, paid checkout using its Stripe session id as an idempotency
 * key. This intentionally persists no customer profile, email, or raw webhook
 * payload: Stripe remains the payment record of truth.
 */
export async function fulfillVerifiedStripeWebhook(event: StripeCheckoutCompletedEvent) {
  if (!isCompletedPremiumCheckout(event)) return { fulfilled: false, persisted: false };

  if (!isSupabaseServerConfigured()) return { fulfilled: true, persisted: false };

  const checkout = event.data!.object!;
  await supabaseAdminRest("entitlements?on_conflict=provider%2Cprovider_reference", {
    method: "POST",
    headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify({
      user_id: null,
      product: PREMIUM_PRODUCT,
      provider: "stripe",
      provider_reference: checkout.id,
      status: "active",
      expires_at: null,
    }),
  });

  return { fulfilled: true, persisted: true };
}

import { createHmac, timingSafeEqual } from "node:crypto";

export interface PremiumEntitlement {
  v: 1;
  product: "threadtales-premium";
  sessionId: string;
  exp: number;
}

function secret() {
  const value = process.env.ENTITLEMENT_SIGNING_SECRET;
  if (!value) throw new Error("ENTITLEMENT_SIGNING_SECRET is not configured.");
  return value;
}

function signPayload(payload: string) {
  return createHmac("sha256", secret()).update(payload).digest("base64url");
}

export function createEntitlementToken(sessionId: string, lifetimeSeconds = 60 * 60 * 24 * 365): string {
  const entitlement: PremiumEntitlement = {
    v: 1,
    product: "threadtales-premium",
    sessionId,
    exp: Math.floor(Date.now() / 1000) + lifetimeSeconds,
  };
  const payload = Buffer.from(JSON.stringify(entitlement), "utf8").toString("base64url");
  return `${payload}.${signPayload(payload)}`;
}

export function verifyEntitlementToken(token: string): PremiumEntitlement | null {
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) return null;
    const expected = Buffer.from(signPayload(payload));
    const actual = Buffer.from(signature);
    if (expected.length !== actual.length || !timingSafeEqual(expected, actual)) return null;
    const entitlement = JSON.parse(Buffer.from(payload, "base64url").toString("utf8")) as PremiumEntitlement;
    if (entitlement.v !== 1 || entitlement.product !== "threadtales-premium" || entitlement.exp <= Math.floor(Date.now() / 1000)) return null;
    return entitlement;
  } catch {
    return null;
  }
}

import type { StoryChapter, StoryThemeId } from "@/platform/types";
import { getStoryTheme } from "@/platform/story/themes";

export type StoryCardPreset = "vertical" | "square" | "portrait";

export const STORY_CARD_PRESETS: Record<StoryCardPreset, { width: number; height: number }> = {
  vertical: { width: 1080, height: 1920 },
  square: { width: 1080, height: 1080 },
  portrait: { width: 1080, height: 1350 },
};

function escapeXml(value: string) {
  return value.replace(/[<>&"']/g, (character) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;", "'": "&apos;" })[character] ?? character);
}

function lines(value: string, max = 28) {
  const words = value.split(/\s+/).filter(Boolean);
  const output: string[] = [];
  let current = "";
  for (const word of words) {
    if (`${current} ${word}`.trim().length > max && current) { output.push(current); current = word; }
    else current = `${current} ${word}`.trim();
  }
  if (current) output.push(current);
  return output.slice(0, 4);
}

export function renderStoryCardSvg(chapter: StoryChapter, preset: StoryCardPreset = "vertical", attribution = true, themeId: StoryThemeId = "midnight") {
  const { width, height } = STORY_CARD_PRESETS[preset];
  const theme = getStoryTheme(themeId);
  const titleLines = lines(chapter.title, preset === "vertical" ? 26 : 32);
  const titleStart = Math.round(height * 0.22);
  const titleSize = preset === "vertical" ? 80 : 64;
  const metricSize = preset === "vertical" ? 150 : 110;
  const metricY = titleStart + titleLines.length * (titleSize + 16) + 100;
  const subtitleY = metricY + (chapter.metric !== undefined ? metricSize + 34 : 20);
  const title = titleLines.map((line, index) => `<text x="${width / 2}" y="${titleStart + index * (titleSize + 16)}" text-anchor="middle" font-size="${titleSize}" font-weight="700" fill="${theme.foreground}">${escapeXml(line)}</text>`).join("");
  const metric = chapter.metric !== undefined ? `<text x="${width / 2}" y="${metricY}" text-anchor="middle" font-size="${metricSize}" font-weight="800" fill="${theme.foreground}">${escapeXml(String(chapter.metric))}</text>` : "";
  const subtitle = chapter.subtitle ? `<text x="${width / 2}" y="${subtitleY}" text-anchor="middle" font-size="38" fill="${theme.muted}">${escapeXml(chapter.subtitle)}</text>` : "";
  const supporting = chapter.supportingText ? `<foreignObject x="${Math.round(width * 0.12)}" y="${subtitleY + 70}" width="${Math.round(width * 0.76)}" height="320"><div xmlns="http://www.w3.org/1999/xhtml" style="font: 34px/1.4 system-ui, sans-serif;color:${theme.muted};text-align:center;">${escapeXml(chapter.supportingText)}</div></foreignObject>` : "";
  const brand = attribution ? `<text x="${width / 2}" y="${height - 70}" text-anchor="middle" font-size="28" letter-spacing="4" fill="${theme.muted}">THREADTALES · PRIVATE BY DEFAULT</text>` : "";
  const [start, middle, end] = theme.background;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${start}"/><stop offset="0.52" stop-color="${middle}"/><stop offset="1" stop-color="${end}"/></linearGradient><radialGradient id="glow"><stop offset="0" stop-color="${theme.accent}" stop-opacity=".22"/><stop offset="1" stop-color="${theme.accent}" stop-opacity="0"/></radialGradient></defs><rect width="100%" height="100%" rx="42" fill="url(#bg)"/><circle cx="${Math.round(width * 0.82)}" cy="${Math.round(height * 0.17)}" r="${Math.round(width * 0.45)}" fill="url(#glow)"/><text x="${width / 2}" y="100" text-anchor="middle" font-size="26" letter-spacing="6" fill="${theme.muted}">${escapeXml(chapter.type.toUpperCase())}</text>${title}${metric}${subtitle}${supporting}${brand}</svg>`;
}

export async function renderStoryCardBlob(chapter: StoryChapter, preset: StoryCardPreset = "vertical", attribution = true, themeId: StoryThemeId = "midnight") {
  if (typeof document === "undefined") throw new Error("Story-card rendering requires a browser.");
  const { width, height } = STORY_CARD_PRESETS[preset];
  const svg = renderStoryCardSvg(chapter, preset, attribution, themeId);
  const svgUrl = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml;charset=utf-8" }));
  const image = new Image();
  image.decoding = "async";
  try {
    await new Promise<void>((resolve, reject) => { image.onload = () => resolve(); image.onerror = () => reject(new Error("Could not render the story card.")); image.src = svgUrl; });
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Canvas export is not available in this browser.");
    context.drawImage(image, 0, 0, width, height);
    return await new Promise<Blob>((resolve, reject) => canvas.toBlob((value) => value ? resolve(value) : reject(new Error("Could not create the image export.")), "image/png", 0.96));
  } finally {
    URL.revokeObjectURL(svgUrl);
  }
}

function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export async function downloadStoryCard(chapter: StoryChapter, preset: StoryCardPreset = "vertical", attribution = true, themeId: StoryThemeId = "midnight") {
  const blob = await renderStoryCardBlob(chapter, preset, attribution, themeId);
  downloadBlob(blob, `threadtales-${chapter.id}-${preset}.png`);
}

export async function shareStoryCard(chapter: StoryChapter, preset: StoryCardPreset = "vertical", attribution = true, themeId: StoryThemeId = "midnight") {
  const blob = await renderStoryCardBlob(chapter, preset, attribution, themeId);
  const file = new File([blob], `threadtales-${chapter.id}-${preset}.png`, { type: "image/png" });
  if (typeof navigator.share !== "function" || (typeof navigator.canShare === "function" && !navigator.canShare({ files: [file] }))) return false;
  try {
    await navigator.share({ title: "ThreadTales", text: "A private chat story made with ThreadTales.", files: [file] });
    return true;
  } catch (error) {
    if (error instanceof DOMException && error.name === "AbortError") return true;
    throw error;
  }
}

export async function downloadStorySet(chapters: StoryChapter[], preset: StoryCardPreset = "vertical", attribution = true, themeId: StoryThemeId = "midnight", includeSensitive = false) {
  const selected = chapters.filter((chapter) => includeSensitive || chapter.privacyLevel === "safe");
  for (let index = 0; index < selected.length; index += 1) {
    const chapter = selected[index];
    const blob = await renderStoryCardBlob(chapter, preset, attribution, themeId);
    downloadBlob(blob, `threadtales-${String(index + 1).padStart(2, "0")}-${chapter.id}-${preset}.png`);
    await new Promise((resolve) => window.setTimeout(resolve, 80));
  }
  return selected.length;
}
